questions.question:
What is the output of this program?
#! /usr/bin/awk -f
BEGIN {
var1="sanfoundry"
var2="linux"
print var1" provides "var2" MCQs "
}

What is the output of the program?
#! /usr/bin/awk -f
BEGIN {
a[1]="sanfoundry"
delete a[1]
print a[1]
}

What is the output of this program?
#! /usr/bin/awk -f
BEGIN {
a=10;
b=10;
print a==b ? "true":"false"
}

What is the output of the program?
#! /usr/bin/awk -f
#This filename is text.awk
BEGIN {
print FILENAME
}

What is the output of this program?
#! /usr/bin/awk -f
BEGIN {
two=2;
two++;
print two
}

What is the output of the program?
#! /usr/bin/awk -f
BEGIN {
a[1,1]=0
a[1,2]=1
a[2,1]=2
a[2,2]=3
for(i=1;i<3;i++) {
for(j=1;j<3;j++) {
print a[i,j]
}
}
}

What is the output of this program?
#! /usr/bin/awk -f
BEGIN {
print "20"<"9" ? "true":"false"
}

Which command on the command line provides the same output as this
executable awk script?
#! /usr/bin/awk -f
BEGIN {
print "sanfoundry"
}

What is the output of this program?
#! /usr/bin/awk -f
BEGIN {
one=10;
two=3;
print (one%two)+10
}

